import numpy as np, itertools
cols=[np.ones_like(x)]; names=['1']
for d in range(1,4):
    for combo in itertools.combinations_with_replacement(range(3),d):
        f=np.ones_like(x)
        for i in combo: f=f*[t,x,v][i]
        cols.append(f); names.append('*'.join('txv'[i] for i in combo))
A=np.column_stack(cols)
c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
print('poly3 nmse',np.mean((A@c-dv_dt)**2)/np.var(dv_dt))
for n,cc in zip(names,c):
    if abs(cc)>0.05: print(n,round(cc,4))

